public static class MathHelper
{
    // Thuật toán tính giai thừa đệ quy đơn giản
    public static long Factorial(int n)
    {
        if (n <= 1) return 1;
        long result = 1;
        for (int i = 2; i <= n; i++) result *= i;
        return result;
    }
}

